def validate(self):
	self._assignment = None
	if self.is_new():
		if self.assigned_by == self.allocated_to:
			assignment_message = frappe._("{0} self assigned this task: {1}").format(
				get_fullname(self.assigned_by), self.description
			)
		else:
			assignment_message = frappe._("{0} assigned {1}: {2}").format(
				get_fullname(self.assigned_by), get_fullname(self.allocated_to), self.description
			)

		self._assignment = {"text": assignment_message, "comment_type": "Assigned"}

	else:
		# NOTE the previous value is only available in validate method
		if self.get_db_value("status") != self.status:
			if self.allocated_to == frappe.session.user:
				removal_message = frappe._("{0} removed their assignment.").format(
					get_fullname(frappe.session.user)
				)
			else:
				removal_message = frappe._("Assignment of {0} removed by {1}").format(
					get_fullname(self.allocated_to), get_fullname(frappe.session.user)
				)

			self._assignment = {"text": removal_message, "comment_type": "Assignment Completed"}

def on_update(self):
	if self._assignment:
		self.add_assign_comment(**self._assignment)

	self.update_in_reference()

def on_trash(self):
	self.delete_communication_links()
	self.update_in_reference()

def add_assign_comment(self, text, comment_type):
	if not (self.reference_type and self.reference_name):
		return

	frappe.get_doc(self.reference_type, self.reference_name).add_comment(comment_type, text)

def delete_communication_links(self):
	# unlink todo from linked comments
	return frappe.db.delete("Communication Link", {"link_doctype": self.doctype, "link_name": self.name})

def update_in_reference(self):
	if not (self.reference_type and self.reference_name):
		return

	try:
		assignments = frappe.db.get_values(
			"ToDo",
			{
				"reference_type": self.reference_type,
				"reference_name": str(self.reference_name),
				"status": ("not in", ("Cancelled", "Closed")),
				"allocated_to": ("is", "set"),
			},
			"allocated_to",
			pluck=True,
			for_update=True,
		)
		assignments.reverse()

		if frappe.get_meta(self.reference_type).issingle:
			frappe.db.set_single_value(
				self.reference_type,
				"_assign",
				json.dumps(assignments) if assignments else "",
				update_modified=False,
			)
		else:
			frappe.db.set_value(
				self.reference_type,
				self.reference_name,
				"_assign",
				json.dumps(assignments) if assignments else "",
				update_modified=False,
			)

	except Exception as e:
		if frappe.db.is_table_missing(e) and frappe.flags.in_install:
			# no table
			return

		elif frappe.db.is_missing_column(e):
			from frappe.database.schema import add_column

			add_column(self.reference_type, "_assign", "Text")
			self.update_in_reference()

		else:
			raise

def get_permission_query_conditions(user):
	if not user:
		user = frappe.session.user

	todo_roles = frappe.permissions.get_doctype_roles("ToDo")
	todo_roles = set(todo_roles) - set(AUTOMATIC_ROLES)

	if any(check in todo_roles for check in frappe.get_roles(user)):
		return None
	else:
		return """(`tabToDo`.allocated_to = {user} or `tabToDo`.assigned_by = {user} or `tabToDo`.owner = {user})""".format(
			user=frappe.db.escape(user)
		)

def has_permission(doc, ptype="read", user=None):
	user = user or frappe.session.user
	todo_roles = frappe.permissions.get_doctype_roles("ToDo", ptype)
	todo_roles = set(todo_roles) - set(AUTOMATIC_ROLES)

	if any(check in todo_roles for check in frappe.get_roles(user)):
		return True
	else:
		return doc.allocated_to == user or doc.assigned_by == user or doc.owner == user

def validate(self):
	self.validate_document_types()
	self.validate_assignment_days()

def validate_document_types(self):
	if self.document_type == "ToDo":
		frappe.throw(
			_("Assignment Rule is not allowed on document type {0}").format(frappe.bold(_("ToDo")))
		)

def validate_assignment_days(self):
	assignment_days = self.get_assignment_days()
	if len(set(assignment_days)) != len(assignment_days):
		frappe.throw(
			_("The following Assignment Days have been repeated: {0}").format(
				comma_and([_(day) for day in get_repeated(assignment_days)], add_quotes=False)
			)
		)

def apply_unassign(self, doc, assignments):
	if self.unassign_condition and self.name in [d.assignment_rule for d in assignments]:
		return self.clear_assignment(doc)

	return False

def apply_assign(self, doc):
	if self.safe_eval("assign_condition", doc):
		return self.do_assignment(doc)

def clear_assignment(self, doc):
	"""Clear assignments"""
	if self.safe_eval("unassign_condition", doc):
		return assign_to.clear(doc.get("doctype"), doc.get("name"), ignore_permissions=True)

def close_assignments(self, doc):
	"""Close assignments"""
	if self.safe_eval("close_condition", doc):
		return assign_to.close_all_assignments(
			doc.get("doctype"), doc.get("name"), ignore_permissions=True
		)

def get_user(self, doc):
	"""
	Get the next user for assignment
	"""
	if self.rule == "Round Robin":
		return self.get_user_round_robin()
	elif self.rule == "Load Balancing":
		return self.get_user_load_balancing()
	elif self.rule == "Based on Field":
		return self.get_user_based_on_field(doc)
	elif self.rule == "Weighted Distribution":
		return self.get_weighted_user()

def get_user_load_balancing(self):
	"""Assign to the user with least number of open assignments"""
	counts = [
		dict(
			user=d.user,
			count=frappe.db.count(
				"ToDo",
				dict(
					reference_type=self.document_type,
					allocated_to=d.user,
					status="Open",
				),
			),
		)
		for d in self.users
	]
	# sort by dict value
	sorted_counts = sorted(counts, key=lambda k: k["count"])

	# pick the first user
	return sorted_counts[0].get("user")

def get_user_based_on_field(self, doc):
	val = doc.get(self.field)
	if frappe.db.exists("User", val):
		return val

def get_weighted_user(self):
	"""
	Assign to the user based on weights assigned to users
	Each rule maintains its own counter.
	"""
	users = [(d.user, d.weight or 1) for d in self.weighted_users if d.user]
	if not users:
		return None

	total_weight = sum(weight for _, weight in users)
	if total_weight <= 0:
		return None

	current_index = (
		frappe.db.get_value("Assignment Rule", self.name, "current_index", for_update=True) or 0
	)
	slot = current_index % total_weight

	cumulative_weight = 0
	for user, weight in users:
		cumulative_weight += weight
		if slot < cumulative_weight:
			frappe.db.set_value(
				"Assignment Rule", self.name, "current_index", current_index + 1, update_modified=False
			)
			return user

def safe_eval(self, fieldname, doc):
	try:
		if self.get(fieldname):
			return frappe.safe_eval(self.get(fieldname), None, doc)
	except Exception as e:
		# when assignment fails, don't block the document as it may be
		# a part of the email pulling
		frappe.msgprint(frappe._("Auto assignment failed: {0}").format(str(e)), indicator="orange")

	return False

def get_assignments(doc) -> list[dict]:
	return frappe.get_all(
		"ToDo",
		fields=["name", "assignment_rule"],
		filters=dict(
			reference_type=doc.get("doctype"), reference_name=str(doc.get("name")), status=("!=", "Cancelled")
		),
		limit=5,
	)

def bulk_apply(doctype: str, docnames: str | list[str]):
	docnames = frappe.parse_json(docnames)
	background = len(docnames) > 5

	for name in docnames:
		if background:
			frappe.enqueue(
				"frappe.automation.doctype.assignment_rule.assignment_rule.apply",
				doc=None,
				doctype=doctype,
				name=name,
			)
		else:
			apply(doctype=doctype, name=name)

def reopen_closed_assignment(doc):
	todo_list = frappe.get_all(
		"ToDo",
		filters={
			"reference_type": doc.doctype,
			"reference_name": str(doc.name),
			"status": "Closed",
		},
		pluck="name",
	)

	for todo in todo_list:
		todo_doc = frappe.get_doc("ToDo", todo)
		todo_doc.status = "Open"
		todo_doc.save(ignore_permissions=True)

	return bool(todo_list)

def apply(doc=None, method=None, doctype=None, name=None):
	doctype = doctype or doc.doctype

	skip_assignment_rules = (
		frappe.flags.in_patch
		or frappe.flags.in_install
		or frappe.flags.in_setup_wizard
		or doctype in log_types
	)

	if skip_assignment_rules:
		return

	if not doc and doctype and name:
		doc = frappe.get_doc(doctype, name)
		doc.check_permission()

	assignment_rules = get_doctype_map(
		"Assignment Rule",
		doc.doctype,
		filters={"document_type": doc.doctype, "disabled": 0},
		order_by="priority desc",
	)

	# multiple auto assigns
	assignment_rule_docs: list[AssignmentRule] = [
		frappe.get_cached_doc("Assignment Rule", d.get("name")) for d in assignment_rules
	]

	if not assignment_rule_docs:
		return

	doc = doc.as_dict()
	assignments = get_assignments(doc)

	clear = True  # are all assignments cleared
	new_apply = False  # are new assignments applied

	if assignments:
		# first unassign
		# use case, there are separate groups to be assigned for say L1 and L2,
		# so when the value switches from L1 to L2, L1 team must be unassigned, then L2 can be assigned.
		clear = False
		for assignment_rule in assignment_rule_docs:
			if assignment_rule.is_rule_not_applicable_today():
				continue

			clear = assignment_rule.apply_unassign(doc, assignments)
			if clear:
				break

	# apply rule only if there are no existing assignments
	if clear:
		for assignment_rule in assignment_rule_docs:
			if assignment_rule.is_rule_not_applicable_today():
				continue

			new_apply = assignment_rule.apply_assign(doc)
			if new_apply:
				break

	# apply close rule only if assignments exists
	assignments = get_assignments(doc)

	if assignments:
		closed_assignments_checked = False
		for assignment_rule in assignment_rule_docs:
			if assignment_rule.is_rule_not_applicable_today():
				continue

			if not new_apply:
				# only reopen if close condition is not satisfied
				to_close_todos = assignment_rule.safe_eval("close_condition", doc)

				if to_close_todos:
					# close todo status
					todos_to_close = frappe.get_all(
						"ToDo",
						filters={
							"reference_type": doc.doctype,
							"reference_name": str(doc.name),
						},
						pluck="name",
					)

					for todo in todos_to_close:
						_todo = frappe.get_doc("ToDo", todo)
						_todo.status = "Closed"
						_todo.save(ignore_permissions=True)
					break

				elif not closed_assignments_checked:
					closed_assignments_checked = True
					reopened = reopen_closed_assignment(doc)
					if reopened:
						break

			assignment_rule.close_assignments(doc)

def update_due_date(doc, state=None):
	"""Run on_update on every Document (via hooks.py)"""
	skip_document_update = (
		frappe.flags.in_migrate
		or frappe.flags.in_patch
		or frappe.flags.in_import
		or frappe.flags.in_setup_wizard
		or frappe.flags.in_install
	)

	if skip_document_update:
		return

	assignment_rules = get_doctype_map(
		doctype="Assignment Rule",
		name=f"due_date_rules_for_{doc.doctype}",
		filters={
			"due_date_based_on": ["is", "set"],
			"document_type": doc.doctype,
			"disabled": 0,
		},
	)

	for rule in assignment_rules:
		rule_doc = frappe.get_cached_doc("Assignment Rule", rule.get("name"))
		due_date_field = rule_doc.due_date_based_on
		field_updated = (
			doc.meta.has_field(due_date_field) and doc.has_value_changed(due_date_field) and rule.get("name")
		)

		if field_updated:
			assignment_todos = frappe.get_all(
				"ToDo",
				filters={
					"assignment_rule": rule.get("name"),
					"reference_type": doc.doctype,
					"reference_name": str(doc.name),
					"status": "Open",
				},
				pluck="name",
			)

			for todo in assignment_todos:
				todo_doc = frappe.get_doc("ToDo", todo)
				todo_doc.date = doc.get(due_date_field)
				todo_doc.flags.updater_reference = {
					"doctype": "Assignment Rule",
					"docname": rule.get("name"),
					"label": _("via Assignment Rule"),
				}
				todo_doc.save(ignore_permissions=True)

def get_repeated(values: Iterable) -> list:
	unique = set()
	repeated = set()

	for value in values:
		if value in unique:
			repeated.add(value)
		else:
			unique.add(value)

	return [str(x) for x in repeated]

def default_get(self, fields):
    res = super().default_get(fields)
    if 'res_model_id' in fields and res.get('res_model'):
        res['res_model_id'] = self.env['ir.model']._get(res['res_model']).id
    return res

def _default_activity_type(self):
    default_vals = self.default_get(['res_model_id', 'res_model'])
    current_model = default_vals.get('res_model')
    if default_vals.get('res_model_id'):
        current_model = self.env["ir.model"].sudo().browse(default_vals['res_model_id']).model
    return self._default_activity_type_for_model(current_model)

def _default_activity_type_for_model(self, model):
    """ Take first one found, ordered by sequence. Keep it simple. """
    if model:
        return self.env['mail.activity.type'].search(['|', ('res_model', '=', model), ('res_model', '=', False)], limit=1)
    return self.env['mail.activity.type'].search([('res_model', '=', False)], limit=1)

def _compute_res_name(self):
    free = self.filtered(lambda a: not a.res_model or not a.res_id)
    free.res_name = False
    for activity in (self - free):
        activity.res_name = activity.res_model and \
            self.env[activity.res_model].browse(activity.res_id).display_name

def _compute_state(self):
    for record in self.filtered(lambda activity: activity.date_deadline):
        tz = record.user_tz
        date_deadline = record.date_deadline
        record.state = 'done' if not record.active else self._compute_state_from_date(date_deadline, tz)

def _get_phone_numbers_by_activity(self):
    """Batch compute the phone numbers associated with the activities.

    :return: phone number for each activity (obtained from the related
        record itself or from its related partner)
    """
    phone_numbers_by_activity = {}
    data_by_model = self.filtered("res_model")._classify_by_model()
    for model, data in data_by_model.items():
        records = self.env[model].browse(data["record_ids"])
        for record, activity in zip(records, data["activities"]):
            try:
                phone = self._get_phone_number_from_record(record)
                if not phone:
                    recipient = next(
                        iter(record._mail_get_partners(introspect_fields=True)[record.id]),
                        self.env["res.partner"],
                    )
                    phone = self._get_phone_number_from_record(recipient) if recipient else False
            # cascade-deleted records might make this crash, be defensive
            except MissingError:
                phone = False
            phone_numbers_by_activity[activity] = phone
    return phone_numbers_by_activity

def _get_phone_number_from_record(self, record):
    """Hook for phone modules to find the phone number of ``record``."""
    return record.phone if "phone" in record else False

def _compute_state_from_date(self, date_deadline, tz=False):
    date_deadline = fields.Date.to_date(date_deadline)
    if tz:
        today = fields.Date.context_today(self.with_context(tz=tz))
    else:
        today = fields.Date.context_today(self)
    diff = (date_deadline - today)
    if diff.days == 0:
        return 'today'
    elif diff.days < 0:
        return 'overdue'
    else:
        return 'planned'

def _compute_can_write(self):
    valid_records = self._filtered_access('write')
    for record in self:
        record.can_write = record in valid_records

def _compute_date_deadline(self):
    for activity in self:
        if activity.activity_type_id.delay_count:
            activity.date_deadline = activity.activity_type_id._get_date_deadline()
        elif not activity.date_deadline:
            activity.date_deadline = fields.Date.context_today(activity)

def _compute_note(self):
    for activity in self.filtered(lambda a: a.activity_type_id.default_note):
        activity.note = activity.activity_type_id.default_note

def _compute_summary(self):
    for activity in self:
        if activity.activity_type_id.summary:
            activity.summary = activity.activity_type_id.summary
        elif not activity.summary:
            activity.summary = activity.activity_type_id.name

def _compute_user_id(self):
    for activity in self:
        if activity.activity_type_id.default_user_id or activity.activity_type_id.default_role_id:
            activity.user_id = activity.activity_type_id.default_user_id
        elif not activity.user_id and not activity.role_id:
            activity.user_id = self.env.user

def _compute_role_id(self):
    for activity in self:
        if activity.activity_type_id.default_user_id or activity.activity_type_id.default_role_id:
            activity.role_id = activity.activity_type_id.default_role_id

def _make_access_error_message(self, operation, domain):
    self.invalidate_recordset()  # avoid cache pollution
    if not domain.is_false():
        return AccessError(self.env._(
            "The requested operation cannot be completed due to security restrictions. "
            "Please contact your system administrator.\n\n"
            "(Document type: %(type)s, Operation: %(operation)s)\n\n"
            "Records: %(records)s, User: %(user)s",
            type=self._description,
            operation=operation,
            records=self.ids[:6],
            user=self.env.uid,
        ))
    return super()._make_access_error_message(operation, domain)

def create(self, vals_list):
    activities = super(MailActivity, self).create(vals_list)

    # find partners related to responsible users, separate readable from unreadable
    if any(user != self.env.user for user in activities.user_id):
        user_partners = activities.user_id.partner_id
        readable_user_partners = user_partners._filtered_access('read')
    else:
        readable_user_partners = self.env.user.partner_id

    # when creating activities for other: send a notification to assigned user;
    if self.env.context.get('mail_activity_quick_update'):
        activities_to_notify = self.env['mail.activity']
    else:
        activities_to_notify = activities.filtered(lambda act: act.user_id != self.env.user)
    if activities_to_notify:
        to_sudo = activities_to_notify.filtered(lambda act: act.user_id.partner_id not in readable_user_partners)
        other = activities_to_notify - to_sudo
        to_sudo.sudo().action_notify()
        other.action_notify()

    # subscribe (batch by model and user to speedup)
    for model, activity_data in activities.filtered('res_model')._classify_by_model().items():
        per_user = defaultdict(set)
        for activity in activity_data['activities'].filtered(lambda act: act.user_id):
            per_user[activity.user_id].add(activity.res_id)
        for user, res_ids in per_user.items():
            pids = user.partner_id.ids if user.partner_id in readable_user_partners else user.sudo().partner_id.ids
            self.env[model].browse(res_ids).message_subscribe(partner_ids=pids)

    # send notifications about activity creation
    today = fields.Date.context_today(activities)
    todo_activities = activities.filtered(lambda act: act.active and act.date_deadline <= today and act.user_id)
    if todo_activities:
        for user, user_activities in todo_activities.grouped('user_id').items():
            user._bus_send("mail.activity/updated", {"activity_created": True, "count_diff": len(user_activities)})
    return activities

def write(self, vals):
    today = fields.Date.context_today(self)

    def get_user_todo_activity_count(activities):
        return {
            user: len(user_activities.filtered(lambda a: a.active and a.date_deadline <= today))
            for user, user_activities in activities.grouped('user_id').items()
            if user
        }

    original_user_todo_activity_count = None
    if 'date_deadline' in vals or 'active' in vals or 'user_id' in vals:
        original_user_todo_activity_count = get_user_todo_activity_count(self)

    new_user_activities = self.env['mail.activity']
    if vals.get('user_id'):
        new_user_activities = self.filtered(lambda activity: activity.user_id.id != vals.get('user_id'))

    res = super().write(vals)

    # notify new responsibles
    if vals.get('user_id'):
        if vals['user_id'] != self.env.uid:
            if not self.env.context.get('mail_activity_quick_update', False):
                new_user_activities.action_notify()
        new_user = self.env['res.users'].browse(vals['user_id'])
        for res_model, model_activities in new_user_activities.filtered(
            lambda activity: activity.res_model and activity.res_id
        ).grouped('res_model').items():
            res_ids = OrderedSet(id_ for id_ in model_activities.mapped('res_id') if id_)
            self.env[res_model].browse(res_ids).message_subscribe(partner_ids=new_user.partner_id.ids)

    # update activity counter
    if original_user_todo_activity_count is not None:
        new_user_todo_activity_count = get_user_todo_activity_count(self)
        users = new_user_todo_activity_count.keys() | original_user_todo_activity_count.keys()
        # sorting users by id to ensure deterministic order because keys views are set-like
        for user in sorted(users, key=lambda user: user.id):
            count_diff = new_user_todo_activity_count.get(user, 0) - original_user_todo_activity_count.get(user, 0)
            if count_diff > 0:
                user._bus_send("mail.activity/updated", {"activity_created": True, "count_diff": count_diff})
            elif count_diff < 0:
                user._bus_send("mail.activity/updated", {"activity_deleted": True, "count_diff": count_diff})

    return res

def unlink(self):
    todo_activities = self.filtered(lambda act: act.active and act.date_deadline <= fields.Date.today() and act.user_id)
    if todo_activities:
        for user, user_activities in todo_activities.grouped('user_id').items():
            user._bus_send("mail.activity/updated", {"activity_deleted": True, "count_diff": -len(user_activities)})
    return super().unlink()

def _search(self, domain, offset=0, limit=None, order=None, *, bypass_access=False, **kwargs):
    """Implement custom access rules and `active_test` behavior.

    This method enhances the standard search in two ways:

    1.  **Archived Records Search**: If the search domain includes a filter on
        the 'Done Date' (`date_done`) field, the search automatically includes
        archived records (`active_test=False`). This allows users to find
        past activities that have been completed and subsequently archived.

    2.  **Custom Access Rights**: It filters search results to only include
        activities the current user is allowed to see. An activity is
        accessible if the user is the assignee (`user_id`), or if they have
        read access to the related document (`res_model`, `res_id`). This
        logic is detailed in res_access* fields.
        Superusers bypass this and perform a standard search.
    """
    domain = Domain(domain).optimize(self)

    if any(
        condition.field_expr == 'date_done' and condition.value
        for condition in domain.iter_conditions()
    ):
        kwargs['active_test'] = False

    # Rules do not apply to administrator or when we search only activities assigned to the current user
    domain = Domain(domain).optimize(self)
    if self.env.su or bypass_access or domain.is_false() or tuple(condition_values(self, 'user_id', domain) or ()) == (self.env.uid,):
        return super()._search(domain, offset, limit, order, bypass_access=bypass_access, **kwargs)
    if self.env.context.get('_generating_sql_for_fields'):
        raise ValueError("Cannot generate SQL for whole mail.activity")

    # search by ids
    if (ids := condition_values(self, 'id', domain)) is not None:
        if (not order or order[:2] == 'id') and domain.map_conditions(lambda d: Domain.TRUE if d.field_expr == 'id' and d.operator == 'in' else d).is_true():
            # trivial domain, can skip search, in most cases check access removes inexisting records
            records = exists_in_cache(self.browse(ids), hint_field='res_model')
            records = records._filtered_access('read')
            if order:
                records = records.sorted(order)
        else:
            records = self.browse(super()._search(domain, order=order, **kwargs))
            records = records._filtered_access('read')
        if offset > 0:
            records = records[offset:]
        if limit is not None:
            records = records[:limit]
        return records._as_query(ordered=bool(order))

    # searching for a subset of models
    res_model_names = condition_values(self, 'res_model', domain) or ()
    if 0 < len(res_model_names) <= MAX_COMODELS_FOR_DOMAIN:
        return super()._search(domain, offset, limit, order, bypass_access=bypass_access, **kwargs)

    self_sudo = self.sudo()
    if self._active_name and not kwargs.get('active_test', True):  # user set active_test=False
        domain &= Domain(self._active_name, 'in', [True, False])
    ordered = bool(order)
    if limit is None:
        records = self_sudo.search_fetch(domain, SECURITY_FIELDS, order=order).sudo(False)
        return records._filtered_access('read')[offset:]._as_query(ordered)
    # Fetch by small batches
    looping_offset = 0
    limit += offset
    result = []
    if not ordered:
        # By default, order by model to batch access checks.
        order = 'res_model nulls first, id'
    while len(result) < limit:
        records = self_sudo.search_fetch(
            domain,
            SECURITY_FIELDS,
            offset=looping_offset,
            limit=IN_MAX,
            order=order,
        ).sudo(False)
        result.extend(records._filtered_access('read')._ids)
        if len(records) < IN_MAX:
            # There are no more records
            break
        looping_offset += IN_MAX
    return self.browse(result[offset:limit])._as_query(ordered)

def _compute_display_name(self):
    for record in self:
        name = record.summary or record.activity_type_id.display_name
        record.display_name = name

def action_done(self):
